  // Every SDK download entry uses this controller's shared lane. Waiting never
  // holds gate, so preparation status and cancellation remain available.
  T WithSteamLane<T>(CancellationToken token,Func<T> work){
   networkLane.Wait(token);
   try{
    token.ThrowIfCancellationRequested();
    return work();
   }finally{
    networkLane.Release();
   }
  }
  object ExecuteNetwork(string action,Dictionary<string,object> payload){
   payload=payload??new Dictionary<string,object>();object receiptValue;HallReceipt receipt=null;if(action=="serverHall"){if(!payload.TryGetValue("_hallReceipt",out receiptValue)||!(receiptValue is HallReceipt))ReserveHall(payload);receipt=(HallReceipt)payload["_hallReceipt"];}string requestId=NetworkId(payload);
   var tokenSource=new CancellationTokenSource();Engine selected;
   lock(gate){if(disposed){tokenSource.Dispose();throw new ObjectDisposedException("ModernController");}if(localMutationBusy){tokenSource.Dispose();throw new Exception("正在修改本地文件，请完成后再查询网络。");}if(receipt!=null&&(receipt.Order!=hallOrder||receipt.Id!=requestId)){tokenSource.Dispose();throw new OperationCanceledException("已忽略被刷新替代的大厅请求。");}if(networkRequests.Count>=16){tokenSource.Dispose();throw new Exception("等待的网络请求过多，请稍后重试。");}selected=engine;if(action=="serverHall")hallRequest=tokenSource;networkRequests.Add(tokenSource);}
   bool acquired=false;
   try{if(action.StartsWith("steam",StringComparison.Ordinal)||action=="serverHall"){networkLane.Wait(tokenSource.Token);acquired=true;}tokenSource.Token.ThrowIfCancellationRequested();var result=networkFetch(selected,action=="serverHall"?"hall":action.StartsWith("steam",StringComparison.Ordinal)?action.Substring(5).ToLowerInvariant():action,payload,(v,t)=>{var callback=Event;if(callback!=null)callback("networkProgress",new{requestId=requestId,value=v,text=t});},tokenSource.Token,batch=>{tokenSource.Token.ThrowIfCancellationRequested();var node=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(new JavaScriptSerializer().Serialize(batch));object rows;if(!node.TryGetValue("servers",out rows))throw new Exception("大厅增量响应缺少服务器列表。");var callback=Event;if(callback!=null)callback("hallBatch",new{requestId=requestId,servers=rows});});tokenSource.Token.ThrowIfCancellationRequested();return result;}
   catch(Exception ex){try{journal.Diagnostic(action+" · 网络读取未完成 · "+ex.Message);}catch{}throw;}
   finally{if(acquired)networkLane.Release();lock(gate){networkRequests.Remove(tokenSource);if(hallRequest==tokenSource)hallRequest=null;}tokenSource.Dispose();}
  }
  public object Execute(string action,Dictionary<string,object> payload){
   if(EnvironmentAction(action))ValidateEnvironmentPayload(action,payload??new Dictionary<string,object>());
   if(EnvironmentPreviewAction(action))return ExecuteEnvironmentPreview(action,payload);
   if(ModWorkshopAction(action))ValidateModWorkshopPayload(action,payload??new Dictionary<string,object>());
   if(LibraryActions.Contains(action))ValidateLibraryPayload(action,payload??new Dictionary<string,object>());
   if(GuideAction(action)){ValidateGuidePayload(action,payload);lock(gate){if(disposed)throw new ObjectDisposedException("ModernController");}return DispatchGuide(action,payload);}
   if(StartupControl(action))return StartupControlRequest(action,payload);
   if(action=="launch"||action=="profileLaunch")ModernHostPolicy.ValidateLaunchPayload(action,payload);
   if(LogAnalysisAction(action))return ExecuteLogAnalysis(action,payload);
   if(FeedbackAction(action))return ExecuteFeedback(action,payload);
   if(action=="maintenance")ModernHostPolicy.ValidateMaintenancePayload(payload);
   if(ServerWorkshopAction(action)){ModernHostPolicy.ValidateWorkshopPayload(action,payload);lock(gate){if(disposed)throw new ObjectDisposedException("ModernController");if(workshopPreparation==null)workshopPreparation=new ServerWorkshopPreparation(data,value=>{var callback=Event;if(callback!=null)callback("serverWorkshopProgress",value);});if(action=="serverWorkshopStatus")return workshopPreparation.Status();if(action=="serverWorkshopCancel")return workshopPreparation.Cancel(Text(payload,"jobId"));var catalog=new ServerWorkshopCatalog(engine,servers);if(action=="serverWorkshopGet")return catalog.Get(Text(payload,"id"));Confirm(payload);if(action=="serverWorkshopImport")return catalog.Import(Text(payload,"id"),Text(payload,"stamp"),Text(payload,"text"));if(busy)throw new Exception("正在处理本机任务，请稍后准备。");var selected=engine;return workshopPreparation.Start(Text(payload,"id"),catalog.Resolve(Text(payload,"id"),Text(payload,"stamp")),(id,progress,token)=>WithSteamLane(token,()=>networkFetch(selected,"download",new Dictionary<string,object>{{"id",id},{"confirmed",true}},progress,token,null)));}}
   if(action=="saveDeletePreview"||action=="saveDelete")ModernHostPolicy.ValidateSaveDeletionPayload(action,payload??new Dictionary<string,object>());
   if(action=="gameDiagnostics"){GameDiagnostics.ValidatePayload(payload);lock(gate){if(disposed)throw new ObjectDisposedException("ModernController");return GameDiagnostics.Read(engine);}}
   if(PlayProfiles.Action(action))PlayProfiles.ValidatePayload(action,payload??new Dictionary<string,object>());
   if(action=="launchPreflight")return StartupPreflight(payload??new Dictionary<string,object>());
   if(ModernHostPolicy.BuddyAction(action))ModernHostPolicy.ValidateBuddyPayload(action,payload??new Dictionary<string,object>());
   if(action=="taskGet")return journal.Snapshot();if(action=="playtimeGet")return PlaytimeTracker.Snapshot(data);
   if(action=="cancel"){if(IsHallCancel(action,payload)){CancelHall(Text(payload,"requestId"));return Message("已停止指定大厅查询，已收到的列表保留。");}Cancel();return Message("已请求取消；当前安全文件阶段完成后停止。");}
   if(NativeNetworkReads.Contains(action))return ExecuteNetwork(action,payload);
   lock(gate){if(disposed)throw new ObjectDisposedException("ModernController");if(action=="setGame"&&networkRequests.Count>0)throw new Exception("网络查询进行中，不能切换安装目录；请取消查询后再选择。");if((action=="buddyTakeover"||action=="buddyRecover")&&networkRequests.Count>0)throw new Exception("Steam 网络任务尚未结束，请先完成或取消查询，再扫描接管。");if(busy)throw new Exception("正在执行任务，请等待完成或取消。");busy=true;localMutationBusy=!NativeReads.Contains(action);cancel.Dispose();cancel=new CancellationTokenSource();}
   if(action=="setGame")try{string selected=GameDiscovery.ResolveSelection(Text(payload,"path"));if(selected.Length==0)throw new Exception("未找到游戏，请选择 Project Zomboid 游戏文件夹或 Steam 游戏库。");payload=new Dictionary<string,object>(payload);payload["path"]=selected;}catch{lock(gate){busy=false;localMutationBusy=false;}throw;}
   bool mutation=!NativeReads.Contains(action);
   if(mutation&&action!="playProfileRecover"&&action!="saveDelete"&&action!="environmentCreate"&&action!="environmentCreateDefault"&&action!="environmentChooseCreate"&&action!="environmentStorageSave"&&PlayProfileTransaction.Pending(engine)&&!SelectingProfileRecoveryOwner(action,payload)){lock(gate){busy=false;localMutationBusy=false;}throw new Exception(PlayProfileTransaction.PendingMessage);}
   try{if(mutation){journal.Begin(action,TaskTitle(action,payload));Report(-1,"正在处理 "+TaskTitle(action,payload));}object result=RunStartupPresentation(action,payload,()=>{if(action=="launch"||action=="profileLaunch"||action=="versionSelect"||action=="forceTakeoverApply"||action=="forceTakeoverRecover")DrainNetworkBeforeLaunch();return Dispatch(action,payload??new Dictionary<string,object>());});if(mutation)FinishTask(result,action,payload);return result;}
   catch(Exception ex){if(!mutation){try{journal.Diagnostic(action+" · 读取失败 · "+ex.Message);}catch{}}if(mutation){journal.Finish(ex is OperationCanceledException?"cancelled":"failed",ex.Message);lock(gate){log.Add(DateTime.Now.ToString("HH:mm:ss")+" "+LauncherJournal.Sanitize(ex.Message));}Report(-1,ex is OperationCanceledException?"任务已取消":ex.Message);}throw;}
   finally{if(mutation)DisplayCache.AfterMutation(engine,action);lock(gate){busy=false;localMutationBusy=false;}}
  }
  LaunchPreflightReport RequireLaunchPreflight(string targetKind="normal",string targetId=null){
   cancel.Token.ThrowIfCancellationRequested();Report(-1,"正在启动游戏…");
   var selected=LaunchEngineContext;var recovery=Stopwatch.StartNew();RecoverLaunchEnvironment(selected,targetKind,targetId);LaunchTiming("preflight-recovery",recovery.ElapsedMilliseconds);cancel.Token.ThrowIfCancellationRequested();
   var javaState=JavaComponentWorkflow.ReconcileBeforeLaunch(selected,cancel.Token,Report);cancel.Token.ThrowIfCancellationRequested();
   var watch=Stopwatch.StartNew();var report=LaunchPreflight.CheckLaunch(selected,false,ClientRunning(),targetKind,targetId,true);
   if(javaState.status!="unchanged"&&javaState.status!="completed")report.items=report.items.Concat(new[]{new LaunchPreflightItem{id="javaReconcile",status="warning",title="Java 组件状态需要核对",message=javaState.message,route="javaMods",details=new string[0]}}).ToArray();
   journal.Diagnostic("启动预检耗时 "+watch.ElapsedMilliseconds+" ms");cancel.Token.ThrowIfCancellationRequested();
   lock(startupGate){RequireAttempt(startupSessionId);}
   if(!report.canLaunch)throw new LaunchPreflightBlockedException(report);return report;
  }
  void ValidateLaunchEvidence(LaunchPreflightReport report){
   var selected=LaunchEngineContext;CheckStorage(selected);if(report.Evidence==null)throw new InvalidOperationException("缺少本次启动检查证据。");
   var watch=Stopwatch.StartNew();report.Evidence.Validate();long evidence=watch.ElapsedMilliseconds;if(LaunchProfiles.Pending(selected))throw new IOException("本次游戏启动状态尚未清理，请重试。");selected.GuardLaunch();ValidateEnvironmentBinding(selected);long guard=watch.ElapsedMilliseconds-evidence;
   string reason=LauncherLaunch.Reason(selected,false,false);if(reason!="")throw new IOException(reason);
   cancel.Token.ThrowIfCancellationRequested();
   journal.Diagnostic("启动提交校验耗时 "+watch.ElapsedMilliseconds+" ms（来源证据 "+evidence+" ms；路径与进程 "+guard+" ms；启动配置 "+(watch.ElapsedMilliseconds-evidence-guard)+" ms）");
   // Stage calls this immediately before its first journal write. Keep the bound
   // attempt cancellable through every fresh read, then commit under startupGate.
   CommitStartup();
  }
