   case "playProfileSelect":return playProfiles.Select(Text(p,"id"),Text(p,"stamp"));
   case "playProfilePreview":return playProfiles.Preview(Text(p,"id"),Text(p,"stamp"));
   case "playProfileApply":return playProfiles.Apply(Text(p,"id"),Text(p,"previewStamp"),Flag(p,"confirmed"));
   case "playProfileExport":return playProfiles.Export(Text(p,"id"),Text(p,"stamp"));
   case "playProfileImport":return playProfiles.Import(Text(p,"json"),Text(p,"stamp"),Flag(p,"confirmed"));
   case "playProfileRecover":return playProfiles.Recover(Text(p,"stamp"),Flag(p,"confirmed"));
   case "status":return Status();
   case "loadingOptions":case "loadingSetEnabled":case "loadingUninstall":return StartupOptions(action,p);
   case "gameProcesses":if(p.Count!=0)throw new Exception("进程预览不接受目标参数。");return clientClose.Preview(CurrentRuntimeEngine().Game);
   case "forceCloseGame":return ForceCloseGame(p);
   case "buddyPreview":return BuddyTakeover.Preview(engine,buddyEnvironment);
   case "buddyTakeover":return BuddyTakeover.Apply(engine,Text(p,"stamp"),Flag(p,"confirmed"),Flag(p,"steamExitConfirmed"),Report,cancel.Token,buddyEnvironment);
   case "buddyRecover":return BuddyTakeover.Recover(engine,Text(p,"stamp"),Flag(p,"confirmed"),Flag(p,"steamExitConfirmed"),Report,cancel.Token,buddyEnvironment);
   case "modProfiles":return ModConfigurations.List(engine);
