   case "modProfileSave":CheckStorage();return ModConfigurations.Save(engine,p);
   case "modProfileDelete":CheckStorage();return ModConfigurations.Delete(engine,Text(p,"id"),Text(p,"stamp"));
   case "modProfileActivate":CheckContent();return ModConfigurations.Activate(engine,Text(p,"id"),Text(p,"stamp"),Flag(p,"confirmed"));
   case "modSort":return ModConfigurations.Sort(engine,ModArray(p));
   case "modAutoSort":ModernHostPolicy.ValidateAutoSortPayload(p);CheckStorage();return ModConfigurations.AutoSortDefault(engine,true);
   case "saveThumb":return LauncherPictures.Save(engine,Text(p,"id"));
   case "serverThumb":return LauncherPictures.Server(engine,servers.Target(Text(p,"id")));
   case "serverFavorites":return GameFavorites.List(engine);
   case "favoriteImport":return GameFavorites.Import(engine,servers,Text(p,"id"),Flag(p,"confirmed"));
   case "playtimeSettings":return PlaytimeTracker.Settings(data,p);
   case "steamConnection":case "steamSubscriptions":case "steamSearch":case "steamDetails":case "serverHall":return SteamLauncherServices.Execute(engine,action=="serverHall"?"hall":action.Substring(5).ToLowerInvariant(),p,Report,cancel.Token);
   case "steamDownload":Confirm(p);Check();return WithSteamLane(cancel.Token,()=>networkFetch(engine,"download",p,Report,cancel.Token,null));
   case "updatesGet":return ComponentEvidence.CheckUpdates(engine,cancel.Token);
   case "profileRecover":return Message(LaunchProfiles.Recover(CurrentRuntimeEngine(),true));
   case "savesList":return SaveProfiles.List(engine);
   case "modCatalog":if(Flag(p,"refresh"))SaveProfiles.InvalidateDisplay(engine);return SaveProfiles.Catalog(engine);
   case "modCover":return SaveProfiles.Cover(engine,Text(p,"token"));
   case "javaList":return JavaApprovals.List(engine);
   case "javaSave":CheckContent();object decision;if(!p.TryGetValue("decision",out decision)||!(decision is bool))throw new Exception("必须明确选择允许或拒绝此文件。");return JavaApprovals.Save(engine,Text(p,"stamp"),Text(p,"hash"),(bool)decision);
   case "saveGet":return SaveProfiles.Read(engine,Text(p,"id"));
   case "saveDeletePreview":return SaveDeletion.Preview(engine,Text(p,"id"));
   case "saveDelete":cancel.Token.ThrowIfCancellationRequested();if(recycleSave==null)return SaveDeletion.Delete(engine,Text(p,"id"),Text(p,"stamp"),Flag(p,"confirmed"),cancel.Token);return SaveDeletion.Delete(engine,Text(p,"id"),Text(p,"stamp"),Flag(p,"confirmed"),recycleSave,cancel.Token);
   case "saveSave":CheckContent();object requested;if(!p.TryGetValue("mods",out requested)||requested is string||!(requested is System.Collections.IEnumerable))throw new Exception("模组清单必须为数组。");var ids=((System.Collections.IEnumerable)requested).Cast<object>().Select(x=>{if(!(x is string))throw new Exception("模组标识必须为文本。");return (string)x;}).ToArray();return SaveProfiles.Save(engine,Text(p,"id"),Text(p,"stamp"),ids,Flag(p,"confirmed"));
   case "serverList":return servers.List();
