  object Status(){ApplySources();return new{gamePath=engine.Game,gameVersion=LauncherStatusMetadata.GameVersion(engine.Game),validGame=File.Exists(engine.Config)&&File.Exists(Path.Combine(engine.Game,"ProjectZomboid64.exe")),running=ClientRunning(),configured=engine.Enabled,buddyFiles=File.Exists(Path.Combine(engine.Game,"ZombieBuddy.jar"))&&File.Exists(Path.Combine(engine.Game,"zbNative.dll")),buddyRecovery=BuddyTakeover.RecoveryStatus(engine),theme=LauncherTheme.Load(data).Light?"light":"dark",launch=LaunchProfiles.State(CurrentRuntimeEngine()),startup=StartupStatus(),hardware=test?HardwareProbe.Unknown():HardwareProbe.Cached(),task=new{active=false,value=progressValue,text=progressText},components=Cards(new[]{Card("base","基础 3D + Buddy","Viewpoint 第一／第三人称视角与 Buddy 加载器。首次使用请完成 Java 授权。","3809306528",engine.Enabled),Card("models","额外 3D 物件","PZVoxelStudioViewpoint 物件模型，需要基础组件。","3810302175",Mod("PZVoxelStudioViewpoint")),Card("shoot","第一人称枪械瞄准","Shoot to Thrill 多人版；使用作者原生控制与个人校准。","3813032735",ShootClient.Enabled(engine)),Card("chinese","游戏内中文","老余汉化 JAVA 版；需简体中文并批准 laoyu.javacn。","3810637496",ChinesePatch.Enabled(engine))}),configStamp=HashPaths(new[]{engine.Config,engine.Mods}.Concat(ViewpointSettings.Files.Select(f=>Path.Combine(user,f))))};}
  object[] Cards(object[] core){core=new[]{Card("buddy","ZombieBuddy · Java 框架","独立 Java 框架；首次使用需完成 Java 授权。","3619862853",CoreComponents.FrameworkReady(engine)),Card("viewpoint","Viewpoint · 第一／第三人称","需要 Buddy；可独立移除视角组件。","3809306528",CoreComponents.ViewpointConfigured(engine))}.Concat(core).ToArray();var result=core.Select(c=>{string key=Convert.ToString(new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(new JavaScriptSerializer().Serialize(c))["id"]);return (object)ComponentEvidence.Decorate(engine,key,c);}).ToList();foreach(var a in ViewpointAddons.All){bool downloaded=false,preload=false;string version="未下载",warning=a.Warning;try{var f=ViewpointAddons.Find(engine,a);downloaded=true;preload=ViewpointAddons.Preload(f);string v;if(f.Metadata.TryGetValue("modversion",out v)||f.Metadata.TryGetValue("version",out v))version=v;else version="作者未声明版本";}catch(Exception ex){warning+=(warning==""?"":" ") +ex.Message;}var card=new{id=a.Key,title=a.Title,description=a.Description,item=a.Item.ToString(),downloaded=downloaded,configured=ViewpointAddons.Enabled(engine,a),version=version,optional=true,preload=preload,warning=warning,compatibility=preload?"客户端预加载":"本地模组",retirement="独立扩展，可按需安装和卸载。"};result.Add(ComponentEvidence.Decorate(engine,a.Key,card));}return result.ToArray();}
  object Card(string id,string title,string description,string item,bool configured){return new{id=id,title=id=="models"?"6244 3D Models · 物件模型":title,description=description,item=item,downloaded=ValidComponent(id),configured=configured,optional=id!="base"&&id!="buddy"&&id!="viewpoint"&&id!="chinese",version=LocalVersion(engine,id,ulong.Parse(item))};}
  static string LocalVersion(Engine e,string key,ulong item){if(key=="buddy")return CoreComponents.Version(e);try{string id=key=="base"||key=="viewpoint"?"Viewpoint":key=="models"?"PZVoxelStudioViewpoint":key=="shoot"?ShootClient.Id:ChinesePatch.Id;var files=ViewpointAddons.Find(e,new ViewpointAddon(key,item,id,key,""));string value;if(files.Metadata.TryGetValue("modversion",out value)||files.Metadata.TryGetValue("version",out value))return value;}catch{}return "本地版本未声明／来源待核对";}
  Dictionary<ulong,string> Download(Engine e,ulong[] ids,Action<int,string> progress,CancellationToken token,bool update){if(test)throw new Exception("测试模式禁止真实工坊下载。");if(!update)return WorkshopWorker.Fetch(e.Game,ids,progress,token,false);var plan=WorkshopUpdate.Check(e,ids,token);if(plan.Needed.Count>0){var downloaded=WorkshopWorker.Fetch(e.Game,plan.Needed.ToArray(),progress,token,true);foreach(var p in downloaded)plan.Paths[p.Key]=p.Value;}return plan.Paths;}
  Dictionary<ulong,string> Fetch(ulong[] ids,bool update){Check();var paths=WithSteamLane(cancel.Token,()=>fetch(engine,ids,(v,t)=>Report(v,t),cancel.Token,update));cancel.Token.ThrowIfCancellationRequested();if(paths==null||ids.Any(id=>!paths.ContainsKey(id)||!Directory.Exists(paths[id])))throw new Exception("下载结果缺少完整条目。");InstallWorkflow.Apply(engine,paths);LauncherMaintenance.NoReparse(data);Directory.CreateDirectory(data);string record=Path.Combine(data,"workshop-paths.json");LauncherMaintenance.NoReparse(record);var all=File.Exists(record)?new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(record)):new Dictionary<string,string>();foreach(var pair in paths)all[pair.Key.ToString()]=pair.Value;File.WriteAllText(record,new JavaScriptSerializer().Serialize(all),new UTF8Encoding(false));return paths;}
  string InstallBase(){Check();bool keepModels=Mod("PZVoxelStudioViewpoint");string result=InstallWorkflow.Enable(engine,keepModels,ids=>Fetch(ids,false));string live=Path.Combine(user,"viewpoint-live.properties");bool hasChoice=File.Exists(live)&&new PropertyDocument(File.ReadAllBytes(live)).Values.ContainsKey("graphics.pack");if(!hasChoice&&File.Exists(Path.Combine(engine.ShaderDir,ShaderSelection.EclipseFile)))result+="\r\n"+new ShaderSelection(user,Path.Combine(data,"backups")).DefaultOnce(Path.Combine(data,"shader-default-installed.txt"),Running());return result;}
  string InstallOptional(string id){Check();if(id=="models"){if(!ValidComponent(id))Fetch(new[]{3810302175UL},false);return Models(true);}if(id=="shoot"){if(!ValidComponent(id))Fetch(new[]{ShootClient.Item},false);return new ShootClient().Enable(engine,InstallWorkflow.Source(engine,ShootClient.Item));}if(id=="chinese"){if(!ValidComponent(id))Fetch(new[]{ChinesePatch.Item},false);return new ChinesePatch().Enable(engine,InstallWorkflow.Source(engine,ChinesePatch.Item));}if(ViewpointAddons.All.Any(a=>a.Key==id)){var a=ViewpointAddons.Get(id);try{ViewpointAddons.Find(engine,a);}catch{Fetch(new[]{a.Item},false);}return ViewpointAddons.Switch(engine,id,true);}throw new Exception("未知组件。");}
  string Batch(IEnumerable<string> ids,Func<string,string> work){var result=new List<string>();foreach(string id in ids){cancel.Token.ThrowIfCancellationRequested();try{result.Add("[完成] "+id+"\r\n"+work(id));}catch(OperationCanceledException){throw;}catch(Exception ex){result.Add("[失败] "+id+"\r\n"+ex.Message);}}return string.Join("\r\n\r\n",result);}
  string Components(string id,string op,Dictionary<string,object> p){if(!new[]{"buddy","viewpoint","base","models","shoot","chinese","all"}.Contains(id)&&!ViewpointAddons.All.Any(a=>a.Key==id)||!new[]{"install","uninstall","update"}.Contains(op))throw new Exception("未知组件或操作。");Check();if(File.Exists(Path.Combine(data,"workshop-rebuild.pending")))throw new Exception("工坊重新下载尚未完成，请先重试维护任务。");if(op=="uninstall"){if(id=="buddy"||id=="viewpoint"){Confirm(p);return engine.SwitchComponent(id,false);}if((id=="base"||id=="all"||id=="roofs")&&Mod("ViewpointTileFix")&&!Flag(p,"roofRemovalAcknowledged"))throw new Exception("完整屋顶可能有已保存标记，请先按作者说明清理，并明确确认屋顶移除提示。");if(id=="base"||id=="all"){Confirm(p);engine.ValidateSwitchJson();string extras=Batch(ViewpointAddons.All.Where(a=>ViewpointAddons.Enabled(engine,a)).Select(a=>a.Key),a=>ViewpointAddons.Switch(engine,a,false));return extras+"\r\n"+(extras.Contains("[完成]")?Batch(new[]{"base"},a=>engine.Switch(false,false)):engine.Switch(false,false));}if(ViewpointAddons.All.Any(a=>a.Key==id))return ViewpointAddons.Switch(engine,id,false);return id=="models"?Models(false):id=="shoot"?new ShootClient().Disable(engine):new ChinesePatch().Disable(engine);}
   if(op=="install"){if(id=="buddy"||id=="viewpoint")return InstallCore(id);if(id=="chinese"){string framework=CoreComponents.FrameworkReady(engine)?"Buddy 已配置。":InstallCore("buddy");return framework+"\r\n"+InstallOptional(id);}if(id=="base")return InstallBase();string basis=ShootClient.BaseReady(engine)&&engine.HasView?"基础组件已配置。":InstallBase();return basis+"\r\n"+Batch(id=="all"?new[]{"models","shoot","chinese"}:new[]{id},InstallOptional);}
   return Batch(id=="all"?new[]{"base","models","shoot","chinese"}:new[]{id},Update);
  }
  string InstallCore(string id){Check();var missing=new List<ulong>();if(!CoreComponents.BuddyDownloaded(engine))missing.Add(CoreComponents.Buddy);if(id=="viewpoint"&&!engine.HasView)missing.Add(CoreComponents.Viewpoint);if(missing.Count>0)Fetch(missing.ToArray(),false);string result=CoreComponents.FrameworkReady(engine)&&id=="viewpoint"?"Buddy 已配置。":engine.SwitchComponent("buddy",true);return id=="viewpoint"?result+"\r\n"+engine.SwitchComponent("viewpoint",true):result;}
  string Update(string id){Check();if(id=="buddy"||id=="viewpoint"){bool coreEnabled=id=="buddy"?CoreComponents.FrameworkReady(engine):CoreComponents.ViewpointConfigured(engine);Fetch(new[]{id=="buddy"?CoreComponents.Buddy:CoreComponents.Viewpoint},true);return coreEnabled?InstallCore(id):"作者文件已核对；原本未启用，保留关闭状态。";}if(ViewpointAddons.All.Any(a=>a.Key==id)){var a=ViewpointAddons.Get(id);bool on=ViewpointAddons.Enabled(engine,a);Fetch(new[]{a.Item},true);return on?ViewpointAddons.Switch(engine,id,true):"作者文件已核对；仍保持未启用。";}bool enabled=id=="base"?engine.Enabled:id=="models"?Mod("PZVoxelStudioViewpoint"):id=="shoot"?ShootClient.Enabled(engine):ChinesePatch.Enabled(engine);string retirement=id=="base"||id=="shoot"?new PresentationBridge().Retire(engine):"";
   try{Fetch(id=="base"?InstallWorkflow.Requested(false):new[]{id=="models"?3810302175UL:id=="shoot"?ShootClient.Item:ChinesePatch.Item},true);string result=enabled?(id=="base"?InstallBase():InstallOptional(id)):"作者文件已核对；原本未启用，保留关闭状态。";return result+(retirement==""?"":"\r\n"+retirement);}
   catch(Exception error){if(retirement=="")throw;string message=error.Message+"\r\n"+retirement;if(error is OperationCanceledException)throw new OperationCanceledException(message,error,((OperationCanceledException)error).CancellationToken);throw new Exception(message,error);}
