  string ModelsUnlocked(bool on){Check();if(on&&!ShootClient.BaseReady(engine))throw new Exception("请先安装基础 3D 和 Buddy。");LauncherMaintenance.NoReparse(engine.Mods);if(!File.Exists(engine.Mods))return "物件模型未启用。";byte[] before=File.ReadAllBytes(engine.Mods);string text=Encoding.UTF8.GetString(before).TrimStart('\uFEFF');var block=Regex.Match(text,@"\bmods\s*\{(?<body>[^}]*)\}");if(!block.Success)throw new Exception("模组列表格式无法识别。");string body=Regex.Replace(block.Groups["body"].Value,@"(?m)^[ \t]*mod\s*=\s*PZVoxelStudioViewpoint\s*,[^\r\n]*(?:\r?\n|$)","");if(on)body=body.TrimEnd()+"\r\n    mod = PZVoxelStudioViewpoint,\r\n";string next=text.Substring(0,block.Groups["body"].Index)+body+text.Substring(block.Groups["body"].Index+block.Groups["body"].Length);if(next==text)return "物件模型状态已保持。";string backup=Path.Combine(data,"backups","models-"+Guid.NewGuid().ToString("N"));LauncherMaintenance.NoReparse(backup);Directory.CreateDirectory(backup);File.WriteAllBytes(Path.Combine(backup,"default.txt"),before);File.WriteAllText(Path.Combine(backup,"人工恢复物件模型.txt"),"退出游戏后仅添加／移除 default.txt 的 PZVoxelStudioViewpoint 行。整份恢复会覆盖后续更改。原路径："+engine.Mods);string temp=engine.Mods+".modern-"+Guid.NewGuid().ToString("N");try{File.WriteAllText(temp,next,new UTF8Encoding(false));Check();if(!File.ReadAllBytes(engine.Mods).SequenceEqual(before))throw new Exception("模组列表已改变，拒绝覆盖。");File.Replace(temp,engine.Mods,null);}finally{if(File.Exists(temp))File.Delete(temp);}return (on?"已启用物件模型。":"已停用物件模型，保留其他组件。")+"\r\n备份："+backup;}
