  static string[] ModArray(Dictionary<string,object> p){object raw;if(!p.TryGetValue("mods",out raw)||raw is string||!(raw is System.Collections.IEnumerable))throw new Exception("模组清单必须为数组。");return ((System.Collections.IEnumerable)raw).Cast<object>().Select(o=>{if(!(o is string))throw new Exception("模组标识必须为文本。");return (string)o;}).ToArray();}
  static string SafeResultMessage(object result,string title){var profile=result as PlayProfileResult;if(profile!=null)return LauncherJournal.Sanitize(profile.message);var buddy=result as BuddyTakeoverResult;if(buddy!=null)return LauncherJournal.Sanitize(buddy.message);if(result!=null){var property=result.GetType().GetProperty("message");if(property!=null){var message=property.GetValue(result,null) as string;if(message!=null)return LauncherJournal.Sanitize(message);}var field=result.GetType().GetField("message",System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Instance);if(field!=null&&field.FieldType==typeof(string)){var text=field.GetValue(result) as string;if(text!=null)return LauncherJournal.Sanitize(text);}var map=result as Dictionary<string,object>;object value;if(map!=null&&map.TryGetValue("message",out value)&&value is string)return LauncherJournal.Sanitize((string)value);}return title;}
  void FinishTask(object result,string action,Dictionary<string,object> payload){string message=SafeResultMessage(result,TaskTitle(action,payload));lock(gate){log.Add(DateTime.Now.ToString("HH:mm:ss")+" "+message);if(log.Count>100)log.RemoveAt(0);}var buddy=result as BuddyTakeoverResult;var profile=result as PlayProfileResult;var javaResult=result as JavaComponents.Result;var javaWorkflow=result as JavaComponentWorkflow.Result;var forceResult=result as ForceTakeover.Result;string raw=buddy!=null?buddy.status:profile!=null?profile.status:javaResult!=null?javaResult.status:javaWorkflow!=null?javaWorkflow.status:forceResult!=null?forceResult.status:null;if(raw!=null){bool completed=raw=="completed"||raw=="recovered"||raw=="unchanged";string status=completed?"completed":raw=="partial"||raw=="recoveryRequired"||raw=="selectionRequired"||raw=="unresolved"?"partial":raw=="cancelled"?"cancelled":"failed";journal.Finish(status,"["+raw+"] "+message);Report(completed?100:-1,message);return;}bool partial=message.Contains("[失败]")||message.Contains("[待清理]");journal.Finish(partial?"partial":"completed",message);Report(partial?-1:100,partial?"部分完成；请核对各组件失败原因、待清理文件和当前配置。":action=="launch"?"启动请求已发送。":action=="profileLaunch"?"所选启动目标已提交。":"操作完成");}
  static string TaskTitle(string action,Dictionary<string,object> p){if(action=="maintenance"){object kind;if(p!=null&&p.TryGetValue("kind",out kind))return Convert.ToString(kind)=="cache"?"清除多人缓存":Convert.ToString(kind)=="cacheAll"?"彻底清除多人本地数据":"重新下载创意工坊模组";}var titles=new Dictionary<string,string>{{"environmentCreate","创建游戏与模组快照"},{"environmentBind","切换存档快照"},{"environmentUnbind","使用当前游戏与模组"},{"forceTakeoverApply","强制接管启动参数与组件"},{"forceTakeoverRecover","恢复强制接管改动"},{"javaComponentsInstall","下载并启用 Java 模组"},{"javaComponentsEnable","启用 Java 模组与依赖"},{"javaComponentsReconcile","核对 Java 停用状态"},{"javaComponentsApply","管理 Java 模组"},{"javaComponentsRecover","恢复 Java 模组操作"},{"worldEditRecover","恢复存档状态"},{"houseTransferApply","迁移房屋区域"},{"versionSelect","切换游戏版本"},{"versionImport","添加已有版本"},{"versionPreserve","保存独立版本"},{"versionInstallBegin","准备 Steam 安装"},{"versionInstallComplete","保存新游戏版本"},{"versionInstallCancel","取消版本安装"},{"backupCreate","备份存档"},{"backupRestore","恢复存档"},{"backupDelete","删除存档备份"},{"backupSettingsSave","保存自动备份设置"},{"playProfileCapture","捕获当前游玩配置"},{"playProfileSave","保存游玩配置"},{"playProfileDelete","删除游玩配置"},{"playProfileSelect","选择游玩配置"},{"playProfileImport","导入游玩配置"},{"playProfileApply","应用已预览的游玩配置"},{"playProfileRecover","恢复游玩配置应用"},{"buddyTakeover","接管旧 Buddy 启动参数"},{"buddyRecover","恢复旧启动参数接管"},{"componentsAction","处理模组组件"},{"memorySave","保存游戏内存"},{"settingsSave","保存 Viewpoint 画面设置"},{"profileLaunch","启动指定存档或服务器"},{"launch","启动游戏"},{"steamDownload","订阅并下载工坊模组"},{"modAutoSort","自动排序默认模组"},{"modProfileActivate","启用模组配置"},{"modProfileSave","保存模组配置"},{"saveSave","保存存档模组清单"},{"playtimeSettings","设置游玩提醒"},{"favoriteImport","导入原版服务器收藏"}};string title;return titles.TryGetValue(action,out title)?title:action;}
  public void Dispose(){CancelEnvironmentPreviews();lock(gate){if(disposed)return;disposed=true;cancel.Cancel();foreach(var request in networkRequests)request.Cancel();if(!busy)cancel.Dispose();}DisposeContentLibrary();DisposeFeedback();DisposeStartup();DisposeLogAnalysis();SaveProfiles.InvalidateDisplay(engine);if(workshopPreparation!=null)workshopPreparation.Dispose();}
